function parseImageRef(ref) {
  const slash = ref.lastIndexOf("/");
  const colon = ref.lastIndexOf(":");
  let tag = "latest";
  let nama = ref;
  if (colon > slash) {
    tag = ref.slice(colon + 1);
    nama = ref.slice(0, colon);
  }
  const bagian = nama.split("/");
  let registry = "docker.io";
  if (bagian.length > 1 && (bagian[0].includes(".") || bagian[0].includes(":") || bagian[0] === "localhost")) {
    registry = bagian.shift();
  }
  let repo = bagian.join("/");
  if (registry === "docker.io" && !repo.includes("/")) repo = "library/" + repo;
  return { registry, repo, tag };
}

