function bangunPerintahRun({ nama, image, ports = [], env = {}, restart }) {
  const bagian = ["docker", "run", "-d", "--name", nama];
  for (const p of ports) bagian.push("-p", p);
  for (const [k, v] of Object.entries(env)) bagian.push("-e", k + "=" + v);
  if (restart) bagian.push("--restart", restart);
  bagian.push(image);
  return bagian.join(" ");
}

