function urutanCacheBenar(dockerfile) {
  const baris = dockerfile.split("\n").map((b) => b.trim());
  const salinPaket = baris.findIndex((b) => /^COPY\s+package/.test(b));
  const pasang = baris.findIndex((b) => /^RUN\s+npm\s+(ci|install)/.test(b));
  const salinSemua = baris.findIndex((b) => /^COPY\s+\.\s+\./.test(b));
  if (salinPaket < 0 || pasang < 0 || salinSemua < 0) return false;
  return salinPaket < pasang && pasang < salinSemua;
}

