function tahapBuild(dockerfile) {
  const hasil = [];
  for (const baris of dockerfile.split("\n")) {
    const m = /^\s*FROM\s+(\S+)(?:\s+AS\s+(\S+))?/i.exec(baris);
    if (m) hasil.push({ nama: m[2] || null, base: m[1] });
  }
  return hasil;
}

