function portBentrok(daftar) {
  const hitung = {};
  for (const entri of daftar) {
    const bagian = entri.split("/")[0].split(":");
    if (bagian.length < 2) continue;
    const host = Number(bagian.length === 3 ? bagian[1] : bagian[0]);
    hitung[host] = (hitung[host] || 0) + 1;
  }
  return Object.keys(hitung).map(Number).filter((p) => hitung[p] > 1).sort((a, b) => a - b);
}

