function urutanStart(services) {
  const hasil = [];
  const sisa = new Set(Object.keys(services));
  while (sisa.size) {
    const siap = [...sisa].sort().find((n) => (services[n].depends_on || []).every((d) => hasil.includes(d)));
    if (!siap) return null;
    hasil.push(siap);
    sisa.delete(siap);
  }
  return hasil;
}

