function parseEnv(teks) {
  const hasil = {};
  for (const baris of teks.split("\n")) {
    const b = baris.trim();
    if (!b || b.startsWith("#")) continue;
    const i = b.indexOf("=");
    if (i < 1) continue;
    let nilai = b.slice(i + 1).trim();
    if (nilai.length >= 2 && (nilai[0] === '"' || nilai[0] === "'") && nilai[nilai.length - 1] === nilai[0]) {
      nilai = nilai.slice(1, -1);
    }
    hasil[b.slice(0, i).trim()] = nilai;
  }
  return hasil;
}

