function tagRollback(riwayat, sekarang) {
  const i = riwayat.lastIndexOf(sekarang);
  if (i < 0) return null;
  for (let j = i - 1; j >= 0; j--) {
    if (riwayat[j] !== sekarang) return riwayat[j];
  }
  return null;
}

