function tagDariRef(ref) {
  const rilis = /^refs\/tags\/v(\d+)\.(\d+)\.(\d+)$/.exec(ref);
  if (rilis) return [rilis[1] + "." + rilis[2] + "." + rilis[3], rilis[1] + "." + rilis[2], "latest"];
  const cabang = /^refs\/heads\/(.+)$/.exec(ref);
  if (cabang) return cabang[1] === "main" ? ["latest"] : [cabang[1].replaceAll("/", "-")];
  return [];
}

