// Membaca Dockerfile menjadi daftar instruksi: { nama, arg }.
// Baris kosong dan komentar dilewati, baris lanjutan (akhiran \) digabung.
function instruksi(teks) {
  const hasil = [];
  let buf = "";
  for (const mentah of teks.split("\n")) {
    const baris = mentah.trim();
    if (!buf && (baris === "" || baris.startsWith("#"))) continue;
    if (baris.endsWith("\\")) {
      buf += baris.slice(0, -1) + " ";
      continue;
    }
    const penuh = (buf + baris).trim();
    buf = "";
    const i = penuh.search(/\s/);
    hasil.push({ nama: (i < 0 ? penuh : penuh.slice(0, i)).toUpperCase(), arg: i < 0 ? "" : penuh.slice(i).trim() });
  }
  return hasil;
}

const RAHASIA = /(PASS|SECRET|TOKEN|KEY)/i;

const pasangan = (arg) => {
  if (!arg.includes("=")) {
    const i = arg.search(/\s/);
    return i < 0 ? [[arg, ""]] : [[arg.slice(0, i), arg.slice(i).trim()]];
  }
  return arg.split(/\s+/).map((t) => {
    const i = t.indexOf("=");
    return i < 0 ? [t, ""] : [t.slice(0, i), t.slice(i + 1)];
  });
};
const tanpaTag = (image) => {
  const nama = image.split("/").pop();
  return !nama.includes(":") || nama.endsWith(":latest");
};

function lintDockerfile(teks) {
  const ins = instruksi(teks);
  const temuan = [];

  const tahap = new Set();
  let latest = false;
  for (const { nama, arg } of ins) {
    if (nama !== "FROM") continue;
    const kata = arg.split(/\s+/).filter((k) => !k.startsWith("--"));
    const image = kata[0];
    if (image !== "scratch" && !tahap.has(image) && tanpaTag(image)) latest = true;
    if (kata[1] && kata[1].toUpperCase() === "AS") tahap.add(kata[2]);
  }
  if (latest) temuan.push("TAG_LATEST");

  const user = ins.filter((i) => i.nama === "USER").pop();
  if (!user || ["root", "0"].includes(user.arg.split(":")[0])) temuan.push("TANPA_USER");

  const bocor = ins.some((i) => (i.nama === "ENV" || i.nama === "ARG") && pasangan(i.arg).some(([k, v]) => RAHASIA.test(k) && v !== ""));
  if (bocor) temuan.push("RAHASIA_DI_ENV");

  const salinSemua = ins.findIndex((i) => i.nama === "COPY" && i.arg.split(/\s+/).filter((k) => !k.startsWith("--"))[0] === ".");
  const pasang = ins.findIndex((i) => i.nama === "RUN" && /npm\s+(ci|install)/.test(i.arg));
  if (salinSemua >= 0 && pasang >= 0 && salinSemua < pasang) temuan.push("CACHE_URUTAN");

  if (!ins.some((i) => i.nama === "HEALTHCHECK")) temuan.push("TANPA_HEALTHCHECK");

  const cmd = ins.filter((i) => i.nama === "CMD").pop();
  if (cmd && !cmd.arg.startsWith("[")) temuan.push("CMD_SHELL_FORM");
  return temuan;
}

function lintCompose(config) {
  const temuan = [];
  for (const [nama, s] of Object.entries(config.services || {})) {
    if (s.image && tanpaTag(s.image)) temuan.push("IMAGE_LATEST:" + nama);

    const terbuka = (s.ports || []).some((p) => {
      const b = String(p).split("/")[0].split(":");
      if (b.length < 2 || b[0] === "127.0.0.1") return false;
      return [5432, 3306, 6379, 27017].includes(Number(b[b.length - 1]));
    });
    if (terbuka) temuan.push("PORT_DB_TERBUKA:" + nama);

    if (!s.restart) temuan.push("TANPA_RESTART:" + nama);

    const env = Array.isArray(s.environment)
      ? s.environment.map((e) => {
          const i = e.indexOf("=");
          return i < 0 ? [e, ""] : [e.slice(0, i), e.slice(i + 1)];
        })
      : Object.entries(s.environment || {});
    const sandi = env.some(([k, v]) => RAHASIA.test(k) && !k.endsWith("_FILE") && v !== "" && v != null && !String(v).startsWith("$" + "{"));
    if (sandi) temuan.push("SANDI_DI_YAML:" + nama);
  }
  return temuan;
}

